1	import React, { useState, useEffect } from 'react';
2	import { Link, useParams } from 'react-router-dom';
3	import { FiChevronLeft, FiChevronRight } from 'react-icons/fi';
4	
5	import api from '../../services/api';
6	
7	import logoImage from '../../assets/logo.svg';
8	import Footer from '../../components/Footer';
9	
10	import { Header, RespositoryInfo, Issues, LoadMoreButton } from './styles';
11	
12	interface Repository {
13	  full_name: string;
14	  description: string;
15	  owner: {
16	    login: string;
17	    avatar_url: string;
18	  };
19	  stargazers_count: number;
20	  forks_count: number;
21	  open_issues_count: number;
22	}
23	interface Issue {
24	  id: number;
25	  title: string;
26	  html_url: string;
27	  user: {
28	    login: string;
29	  };
30	}
31	
32	const ISSUES_PER_PAGE = 10;
33	
34	const Repository: React.FC = () => {
35	  const { '*': repositoryName } = useParams();
36	  const [repository, setRepository] = useState<Repository | null>(null);
37	  const [issues, setIssues] = useState<Issue[]>([]);
38	  const [currentPage, setCurrentPage] = useState(1);
39	  const [hasMoreIssues, setHasMoreIssues] = useState(true);
40	  const [isLoading, setIsLoading] = useState(false);
41	
42	  const fetchIssues = (page: number) => {
43	    setIsLoading(true);
44	    api
45	      .get(`/repos/${repositoryName}/issues`, {
46	        params: {
47	          page,
48	          per_page: ISSUES_PER_PAGE,
49	          state: 'open',
50	          sort: 'created',
51	          direction: 'desc',
52	        },
53	      })
54	      .then((response) => {
55	        const newIssues = response.data as Issue[];
56	        if (page === 1) {
57	          setIssues(newIssues);
58	        } else {
59	          setIssues((prevIssues) => [...prevIssues, ...newIssues]);
60	        }
61	        setHasMoreIssues(newIssues.length === ISSUES_PER_PAGE);
62	        setIsLoading(false);
63	      })
64	      .catch(() => {
65	        setIsLoading(false);
66	      });
67	  };
68	
69	  useEffect(() => {
70	    api.get(`/repos/${repositoryName}`).then((response) => {
71	      setRepository(response.data);
72	    });
73	    fetchIssues(1);
74	  }, [repositoryName]);
75	
76	  const handleLoadMore = () => {
77	    fetchIssues(currentPage + 1);
78	    setCurrentPage(currentPage + 1);
79	  };
80	
81	  return (
82	    <>
83	      <Header>
84	        <img src={logoImage} alt="Github Explorer" />
85	        <Link to="/">
86	          <FiChevronLeft size={16} color="#3D3D4D" />
87	          <strong>Voltar</strong>
88	        </Link>
89	      </Header>
90	      {repository ? (
91	        <RespositoryInfo>
92	          <header>
93	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
94	            <div>
95	              <strong>{repository.full_name}</strong>
96	              <p>{repository.description}</p>
97	            </div>
98	          </header>
99	          <ul>
100	            <li>
101	              <strong>{repository.stargazers_count}</strong>
102	              <span>Stars</span>
103	            </li>
104	            <li>
105	              <strong>{repository.forks_count}</strong>
106	              <span>Forks</span>
107	            </li>
108	            <li>
109	              <strong>{repository.open_issues_count}</strong>
110	              <span>Issues abertos</span>
111	            </li>
112	          </ul>
113	        </RespositoryInfo>
114	      ) : (
115	        <p>Carregando informações.</p>
116	      )}
117	
118	      <Issues>
119	        {issues.map((issue) => (
120	          <a key={issue.id} href={issue.html_url}>
121	            <div>
122	              <strong>{issue.title}</strong>
123	              <p>{issue.user.login}</p>
124	            </div>
125	            <FiChevronRight size={20} />
126	          </a>
127	        ))}
128	      </Issues>
129	
130	      {hasMoreIssues && (
131	        <LoadMoreButton onClick={handleLoadMore} disabled={isLoading}>
132	          {isLoading ? 'Carregando...' : 'Carregar mais'}
133	        </LoadMoreButton>
134	      )}
135	
136	      <Footer />
137	    </>
138	  );
139	};
140	
141	export default Repository;
